    }
    for (const json& item : output) {
        if (!item.is_object() || item.value("type", "") != "function_call")
            continue;
        const std::string call_id = item.value("call_id", "");
        ToolRequest request{item.value("name", ""), item.value("arguments", "{}")};
        const ToolDefinition* definition = ToolRegistry::instance().find(request.tool);
        const bool available = !m_title_request && definition != nullptr && available_in_app(*definition, m_allow_import, m_session.tool_names);
        ToolValidationResult validation;
        if (available)
            validation = ToolRegistry::instance().validate_call(*definition, request.arguments_json);
        // A call to no tool of this turn, or with arguments that miss the
        // tool's contract, never reaches a card. The model gets the refusal as
        // that call's result and may correct it, a bounded number of times
        // per turn.
        constexpr unsigned kRejectedCallLimit = 2;
        if ((!available || !validation.valid()) && m_config.refusal_listener)
            m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
        if (!call_id.empty() && !m_title_request && (!available || !validation.valid()) &&
            m_rejected_calls < kRejectedCallLimit) {
            ++m_rejected_calls;
            json error = available ?
                json{{"code", validation.error->code},
                     {"message", validation.error->message +
                                     " Nothing was proposed. Check the arguments against this tool's parameters and call it again."}} :
                json{{"code", "unknown_tool"},
                     {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was proposed. Use one of the listed tools."}};
            json refusal{{"state", "failed"}, {"error", std::move(error)}};
            json input = m_input_history;
            input.push_back(json{{"type", "function_call_output"}, {"call_id", call_id}, {"output", refusal.dump()}});
            if (!post(std::move(input)))
                fail(AgentError{"agent_continuation_failed", "The Agent could not be told its tool arguments were invalid.", true});
            return;
        }
        if (call_id.empty() || !available || !validation.valid()) {
            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool proposal.", false});
            return;
        }
        request.arguments_json = std::move(validation.arguments_json);
        m_pending_call_id = call_id;
        m_waiting_for_tool = true;
    } else {
        activity.title = "Unknown tool request";
    }

    m_activities.emplace_back(std::move(activity));
    ToolActivity& stored = m_activities.back();

    if (definition == nullptr) {
        fail(stored, "unknown_tool", "This build has no tool named \"" + request.tool + "\".");
        return stored;
    }

    ToolValidationResult validation = m_registry.validate_call(*definition, request.arguments_json);
    if (!validation.valid()) {
        fail(stored, validation.error->code, validation.error->message);
        return stored;
    }
    stored.arguments_json = std::move(validation.arguments_json);
    {
        const json arguments = json::parse(stored.arguments_json);
        stored.plan_id       = arguments.value("planId", "");
        stored.plan_scope    = stored.plan_id.empty() ? std::string() : plan_scope;
        // A plan waits for its card as a whole, including the members that
        // would otherwise run without one.
        if (!stored.plan_id.empty())
            stored.requires_approval = true;
        // A plan takes members only while its card is undecided and whole.
        const bool closed = std::any_of(m_activities.begin(), m_activities.end(), [&stored](const ToolActivity& member) {
            return member.action_id != stored.action_id && same_plan(member, stored) && member.state != ToolState::Pending;
        });
        if (!stored.plan_id.empty() && closed) {
            fail(stored, issue.code, issue.message, settings_preview_result(preview, snapshot).dump());
            return stored;
        }
        if (target.target.object) {
            stored.title = "Change " + std::to_string(preview.changes.size()) + " settings of " + target.object_name + ":";
            for (std::size_t index = 0; index < preview.changes.size(); ++index)
                stored.title += (index == 0 ? " " : ", ") + preview.changes[index].key;
            if (stored.title.size() > kToolLabelLimit) stored.title.resize(kToolLabelLimit - 3), stored.title += "...";
        }
        arguments["confirmedChanges"] = json::array();
        for (const auto& change : Workspace::settings_confirmation(preview))
            arguments["confirmedChanges"].push_back({{"key", change.key}, {"before", change.before}, {"after", change.after}});
        stored.arguments_json = arguments.dump();
    }

    // A surface's own tool is checked by that surface before any card: what
    // is valid there depends on what the surface is about, which the registry
    // cannot know.
    if (m_extension_preflight) {
        if (std::optional<ToolError> problem = m_extension_preflight(definition->handler, stored)) {
            fail(stored, problem->code, problem->message);
            return stored;
        }
